from pathlib import Path
import sys

root=Path(sys.argv[1])
app=root/'public'/'app.js'
cssp=root/'public'/'styles.css'
a=app.read_text()


def bounds(name):
    starts=[a.find(f'function {name}('),a.find(f'async function {name}(')]
    starts=[x for x in starts if x>=0]
    if not starts: raise SystemExit(f'Função não encontrada: {name}')
    p=min(starts); ends=[]
    for token in ['\nfunction ','\nasync function ']:
        q=a.find(token,p+1)
        if q>p: ends.append(q)
    return p,(min(ends) if ends else len(a))

def replace_func(name,code):
    global a
    p,q=bounds(name);a=a[:p]+code+a[q:]

# -----------------------------------------------------------------------------
# Estratégia de metas: usa histórico real, prazo e saldo restante.
# -----------------------------------------------------------------------------
strategy_helpers=r'''function ritmoMonthsInclusive(fromIso,toIso){if(!fromIso||!toIso)return 1;const a=new Date(fromIso+'T12:00:00'),b=new Date(toIso+'T12:00:00');return Math.max(1,(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth()+1)}
function ritmoMonthsUntil(deadline){if(!deadline)return 0;const t=new Date(financeToday()+'T12:00:00'),d=new Date(deadline+'T12:00:00');if(d<t)return 0;return Math.max(1,(d.getFullYear()-t.getFullYear())*12+d.getMonth()-t.getMonth()+1)}
function ritmoFriendlyAmount(v){if(!Number.isFinite(v)||v<=0)return 0;const step=v<100?10:v<500?25:v<1500?50:100;return Math.ceil(v/step)*step}
function goalStrategy(g){const contribs=state.data.goal_contributions.filter(c=>c.goal_id===g.id&&(!c.date||c.date<=financeToday())).sort((x,y)=>String(x.date||'').localeCompare(String(y.date||''))),target=Number(g.target_amount||0),current=Number(g.current_amount||0),remaining=Math.max(0,target-current),first=contribs[0]?.date||financeToday(),elapsed=ritmoMonthsInclusive(first,financeToday()),avg=contribs.length?contribs.reduce((s,c)=>s+Number(c.amount||0),0)/elapsed:0,months=ritmoMonthsUntil(g.deadline),required=months?remaining/months:0,joint=!!g.shared||state.data.scope==='shared';let headline='',summary='',tips=[];
  if(remaining<=0)return {done:true,headline:'Meta alcançada 🎉',summary:'Objetivo concluído. Agora você pode manter o hábito e direcionar os próximos aportes para outra prioridade.',tips:[]};
  if(months){const monthly=ritmoFriendlyAmount(required),weekly=ritmoFriendlyAmount(required/4.33);if(avg>0&&avg>=required){const est=Math.max(1,Math.ceil(remaining/avg));headline='Você está no ritmo';summary=`Mantendo sua média de ${money(avg)} por mês, a tendência é concluir em cerca de ${est} mês(es).`;tips.push(`Reserve aproximadamente ${money(weekly)} por semana para proteger esse ritmo.`)}else if(avg>0){const gap=ritmoFriendlyAmount(required-avg);headline='Dá para acelerar';summary=`Seu ritmo médio é ${money(avg)}/mês. Para chegar até ${dateBR(g.deadline)}, mire em cerca de ${money(monthly)}/mês.`;tips.push(`Um reforço de aproximadamente ${money(gap)} por mês coloca a meta no ritmo do prazo.`);tips.push(`Divida o aporte em cerca de ${money(weekly)} por semana para ficar mais leve.`)}else{headline='Monte seu ritmo';summary=`Para chegar até ${dateBR(g.deadline)}, comece com cerca de ${money(monthly)} por mês.`;tips.push(`Uma referência simples é separar cerca de ${money(weekly)} por semana.`)}if(joint)tips.push(`Se preferirem dividir igualmente, a referência é cerca de ${money(monthly/2)} por pessoa/mês.`)}
  else if(avg>0){const est=Math.max(1,Math.ceil(remaining/avg)),boost=ritmoFriendlyAmount(avg*.15),faster=Math.max(1,Math.ceil(remaining/(avg+boost)));headline='Seu ritmo atual';summary=`Com a média de ${money(avg)} por mês, faltam aproximadamente ${est} mês(es) para concluir.`;tips.push(`Se aumentar o aporte em cerca de ${money(boost)} por mês, a estimativa cai para aproximadamente ${faster} mês(es).`);tips.push(`Transforme o aporte mensal em uma rotina semanal de cerca de ${money(ritmoFriendlyAmount(avg/4.33))}.`);if(joint)tips.push('Nas metas do casal, acompanhem quem aportou sem misturar as despesas pessoais.')}
  else{const m12=ritmoFriendlyAmount(remaining/12),m6=ritmoFriendlyAmount(remaining/6);headline='Escolha um ritmo';summary=`Ainda não há histórico suficiente para projetar essa meta.`;tips.push(`Para concluir em 12 meses, uma referência é ${money(m12)} por mês.`);tips.push(`Para concluir em 6 meses, a referência sobe para ${money(m6)} por mês.`);if(joint)tips.push(`Em uma divisão igual, o plano de 12 meses seria cerca de ${money(m12/2)} por pessoa/mês.`)}
  return {done:false,headline,summary,tips,avg,required,remaining}}
function goalStrategyHtml(g){const s=goalStrategy(g);return `<details class="goal-strategy ${s.done?'done':''}"><summary><span class="goal-strategy-icon">${ic(s.done?'check':'spark',16)}</span><div><strong>${esc(s.headline)}</strong><small>${esc(s.summary)}</small></div><span class="strategy-chevron">${ic('chev',14)}</span></summary>${s.tips.length?`<div class="goal-strategy-body">${s.tips.map(t=>`<div class="strategy-tip"><span>${ic('check',12)}</span><p>${esc(t)}</p></div>`).join('')}</div>`:''}</details>`}
function recordPrivacyBadge(x){return `<span class="record-scope-badge ${x?.shared?'shared':'personal'}">${x?.shared?`${ic('users',11)} Do casal`:`${ic('user',11)} Pessoal`}</span>`}
function debtEventLabel(e){const av=e?.kind==='pagamento'&&String(e?.notes||'').startsWith('[AV]');return av?'AV / Abatimento':e?.kind==='pagamento'?'Pagamento':'Haver'}
'''
# Insere antes de goalCard para manter helpers disponíveis em todas as telas.
p,_=bounds('goalCard')
a=a[:p]+strategy_helpers+'\n'+a[p:]

replace_func('goalCard',r'''function goalCard(g){const pct=Math.min(100,Math.round((g.current_amount/g.target_amount)*100||0)),joint=!!g.shared||state.data.scope==='shared',contribs=state.data.goal_contributions.filter(c=>c.goal_id===g.id);return `<article class="goal-card"><div class="goal-head"><div><div class="goal-badge-row">${recordPrivacyBadge(g)}<div class="goal-scope-badge ${joint?'joint':'solo'}">${joint?`${ic('users',12)} Juntos`:`${ic('user',12)} Individual`}</div></div><h3>${esc(g.name)}</h3><div class="meta">${esc(g.category)}${g.deadline?` • até ${dateBR(g.deadline)}`:''}${authorNote(g)}</div></div><span class="status ${pct>=100?'paid':'pending'}">${pct}%</span></div><div class="card-number">${money(g.current_amount)}</div><div class="card-sub">de ${money(g.target_amount)}</div><div class="progress"><i style="width:${pct}%"></i></div>${goalStrategyHtml(g)}${joint&&contribs.length?`<div class="goal-contribs">${contribs.slice(0,4).map(c=>`<div><span><b>${esc((c.user_name||'Parceiro').split(' ')[0])}</b> • ${dateBR(c.date)}</span><strong>+ ${money(c.amount)}</strong></div>`).join('')}</div>`:''}<div class="debt-actions"><button class="btn btn-secondary" data-goal-add="${g.id}">Adicionar valor</button><button class="btn btn-secondary" data-edit="goal" data-id="${g.id}">Editar</button></div><div class="card-actions"><button class="mini-btn" data-delete="goal" data-id="${g.id}">${ic('trash',12)} Excluir meta</button></div></article>`}''')

