replace_func('debtCard',r'''function debtCard(d){const balance=debtCurrentBalance(d),paid=debtCurrentPaid(d),pct=d.total_amount?Math.min(100,Math.round(paid/d.total_amount*100)):0,events=state.data.debt_events.filter(e=>e.debt_id===d.id),st=debtDueState(d);return `<article class="debt-card"><div class="debt-head"><div><div class="debt-badge-row">${recordPrivacyBadge(d)}</div><h3>${esc(d.creditor)}</h3><div class="meta">Valor original ${money(d.total_amount)}${d.due_date?` • vence ${dateBR(d.due_date)}`:''}${authorNote(d)}</div></div><span class="status ${st.cls}">${st.label}</span></div><div class="card-number">${money(balance)}</div><div class="card-sub">saldo devedor atual</div><div class="progress"><i style="width:${pct}%"></i></div><div class="card-sub">${pct}% efetivamente abatido</div><div class="debt-actions debt-actions-smart"><button class="btn btn-secondary" data-debt-payment="${d.id}" ${balance<=0?'disabled':''}>Pagamento</button><button class="btn btn-secondary debt-av-btn" data-debt-av="${d.id}" ${balance<=0?'disabled':''}>AV / Abatimento</button><button class="btn btn-secondary" data-debt-credit="${d.id}" ${balance<=0?'disabled':''}>Haver</button></div>${events.length?`<div class="event-list">${events.slice(0,5).map(e=>`<div class="event ${e.date>financeToday()?'future-event':''}"><span>${debtEventLabel(e)} • ${dateBR(e.date)}${e.date>financeToday()?' • futuro':''}${authorNote(e)}</span><div><strong>${money(e.amount)}</strong> <button class="mini-btn" data-delete-event="${e.id}" aria-label="Excluir lançamento">×</button></div></div>`).join('')}</div>`:''}<div class="card-actions"><button class="mini-btn" data-edit="debt" data-id="${d.id}">${ic('edit',12)} Editar</button><button class="mini-btn" data-delete="debt" data-id="${d.id}">${ic('trash',12)} Excluir</button></div></article>`}''')

replace_func('itemMoney',r'''function itemMoney(x,type){const st=type==='income'?incomeState(x):expenseState(x),isIncome=type==='income',linked=x.origin==='divida'&&x.debt_event_id,event=linked?state.data.debt_events.find(e=>e.id===x.debt_event_id):null,av=event&&debtEventLabel(event)==='AV / Abatimento';return `<article class="item-card"><div class="item-line"><div><div class="item-badge-row">${recordPrivacyBadge(x)}${linked?`<span class="linked-debt-badge">${ic('wallet',11)} ${av?'AV vinculado':'Vinculado à dívida'}</span>`:''}</div><h3>${esc(x.description)}</h3><p>${esc(x.category)} • ${dateBR(x.date)}${x.due_date?` • vence ${dateBR(x.due_date)}`:''}${authorNote(x)}</p><span class="status ${st.cls}">${st.label}</span></div><span class="amount ${isIncome?'in':'out'}">${isIncome?'+':'−'} ${money(x.amount)}</span></div><div class="card-actions">${linked?`<button class="mini-btn" data-open-debt="${x.debt_id||''}">${ic('wallet',12)} Gerenciar na dívida</button>`:`<button class="mini-btn" data-edit="${type}" data-id="${x.id}">${ic('edit',12)} Editar</button>${isIncome&&!incomeIsRealized(x)?`<button class="mini-btn" data-receive-income="${x.id}">${ic('check',12)} Marcar recebido</button>`:''}${!isIncome&&!expenseIsRealized(x)?`<button class="mini-btn" data-pay-expense="${x.id}">${ic('check',12)} Marcar pago</button>`:''}<button class="mini-btn" data-delete="${type}" data-id="${x.id}">${ic('trash',12)} Excluir</button>`}</div></article>`}''')

