replace_func('sharingPage',r'''function sharingPage(){const sh=state.data.sharing||{},me=state.data.profile;if(sh.active){const partner=sh.partner||{},sharedNow=state.data.scope==='shared',s=sharedNow?currentStats():null;return `${head('Compartilhamento','Vida em comum sem abrir mão da individualidade.')}<div class="sharing-hero smart-couple-hero panel"><div class="couple-avatars"><span>${initials(me.name)}</span><i>${ic('users',18)}</i><span>${initials(partner.name)}</span></div><span class="eyebrow">RITMO A DOIS</span><h2>${esc(me.name.split(' ')[0])} & ${esc((partner.name||'Parceiro').split(' ')[0])}</h2><p>O que é <strong>Pessoal</strong> continua privado. Só aparece para os dois aquilo que vocês cadastrarem como <strong>Do casal</strong>.</p></div><div class="couple-space-grid"><article class="couple-space-card personal"><span class="couple-space-icon">${ic('user',20)}</span><div><strong>Só meu</strong><small>Salário, compras, assinaturas e despesas que dizem respeito apenas a você.</small></div><button class="mini-btn" data-scope="personal">${state.data.scope==='personal'?'Você está aqui':'Abrir Meu Ritmo'}</button></article><article class="couple-space-card shared"><span class="couple-space-icon">${ic('users',20)}</span><div><strong>Do casal</strong><small>Casa, contas em comum, dívidas conjuntas e metas dos dois.</small></div><button class="mini-btn" data-scope="shared">${sharedNow?'Você está aqui':'Abrir Nosso Ritmo'}</button></article></div><div class="panel couple-quick-panel"><div class="panel-title"><div><h3>Adicionar para os dois</h3><small>Sem precisar trocar de espaço antes.</small></div></div><div class="couple-quick-actions"><button data-shared-quick="expense">${ic('down',18)}<span><strong>Conta da casa</strong><small>Água, luz, mercado...</small></span></button><button data-shared-quick="debt">${ic('wallet',18)}<span><strong>Dívida conjunta</strong><small>Compromisso dos dois</small></span></button><button data-shared-quick="goal">${ic('target',18)}<span><strong>Meta juntos</strong><small>Viagem, casa, reserva...</small></span></button></div></div>${sharedNow&&s?`<div class="panel couple-summary"><div class="panel-title"><div><h3>Resumo do casal</h3><small>Somente dados do Nosso Ritmo.</small></div></div><div class="couple-summary-grid"><div><span>A pagar</span><strong>${money(s.pending)}</strong></div><div><span>Dívidas</span><strong>${money(s.debt)}</strong></div><div><span>Metas</span><strong>${state.data.goals.length}</strong></div></div></div>`:''}<div class="panel couple-privacy"><div class="panel-title"><div><h3>Privacidade por padrão</h3><small>Uma conta não enxerga o espaço pessoal da outra.</small></div></div><div class="privacy-rows"><div>${ic('lock',16)}<span><strong>Despesas pessoais</strong><small>Ficam somente na sua conta.</small></span></div><div>${ic('users',16)}<span><strong>Contas em comum</strong><small>Os dois podem acompanhar e administrar.</small></span></div><div>${ic('user',16)}<span><strong>Identidade separada</strong><small>Cada pessoa mantém login, senha e biometria próprios.</small></span></div></div></div>`}
  const incoming=sh.incoming_invites||[],outgoing=sh.outgoing_invites||[];return `${head('Compartilhamento','Conecte duas contas do Ritmo sem compartilhar senha.')}<div class="sharing-grid setup"><div class="panel share-setup-card"><span class="sharing-big-icon">${ic('users',28)}</span><h2>Ritmo a dois</h2><p>Convide seu parceiro pelo nome de usuário. Depois de conectar, cada lançamento pode ser marcado como <strong>Só meu</strong> ou <strong>Do casal</strong>.</p><form id="shareInviteForm"><label class="field">Usuário do parceiro<input name="username" autocomplete="off" placeholder="Ex.: maria.silva" required minlength="3"></label><button class="btn btn-primary" type="submit">Criar convite</button></form></div><div class="panel"><div class="panel-title"><div><h3>Tenho um código</h3><small>Use o código recebido do seu parceiro.</small></div></div><form id="shareCodeForm" class="share-code-form"><input name="code" maxlength="10" placeholder="CÓDIGO" autocomplete="off" required><button class="btn btn-secondary" type="submit">Conectar</button></form></div></div>${incoming.length?`<section class="share-list"><h3>Convites recebidos</h3>${incoming.map(i=>`<article class="share-invite"><span class="mini-avatar">${initials(i.inviter_name)}</span><div><strong>${esc(i.inviter_name)}</strong><small>@${esc(i.inviter_username)} quer compartilhar o Ritmo com você.</small></div><div class="invite-actions"><button class="btn btn-primary" data-share-accept="${i.id}">Aceitar</button><button class="mini-btn" data-share-decline="${i.id}">Recusar</button></div></article>`).join('')}</section>`:''}${outgoing.length?`<section class="share-list"><h3>Convite enviado</h3>${outgoing.map(i=>`<article class="share-invite code"><span class="mini-avatar">${initials(i.invitee_name)}</span><div><strong>${esc(i.invitee_name)}</strong><small>@${esc(i.invitee_username)} • válido por 7 dias</small><button class="invite-code" data-copy-code="${esc(i.code)}">${esc(i.code)} ⧉</button></div><button class="mini-btn" data-share-cancel="${i.id}">Cancelar</button></article>`).join('')}</section>`:''}`}''')

# Submit universal: novos registros escolhem Pessoal/Do casal sem mudar a visão atual.
replace_func('submitData',r'''async function submitData(e){e.preventDefault();const f=new FormData(e.currentTarget),o=Object.fromEntries(f.entries()),m=state.modal;for(const k of ['amount','total_amount','target_amount'])if(k in o)o[k]=Number(o[k]);if(m.type==='credit')o.cash_received=f.get('cash_received')==='on';const chosen=o.record_scope||o.goal_scope||m.recordScope;let targetScope=state.data.scope;if(['income','expense','debt','goal'].includes(m.type)&&!m.item&&chosen)targetScope=chosen==='shared'?'shared':'personal';delete o.record_scope;delete o.goal_scope;if(m.av){o.notes=`[AV]${o.notes?` ${o.notes}`:''}`.trim()}const prefix=scopePrefix(targetScope);let path='',method='POST';if(['income','expense','debt','goal'].includes(m.type)){const plural={income:'incomes',expense:'expenses',debt:'debts',goal:'goals'}[m.type];path=`${prefix}/${plural}${m.item?`/${m.item.id}`:''}`;method=m.item?'PATCH':'POST'}else if(m.type==='payment')path=`${scopePrefix()}/debts/${m.debtId}/payment`;else if(m.type==='credit')path=`${scopePrefix()}/debts/${m.debtId}/credit`;else if(m.type==='contribution')path=`${scopePrefix()}/goals/${m.goalId}/contributions`;try{await api(path,{method,body:JSON.stringify(o)});state.data=await api('/api/bootstrap');state.modal=null;renderApp(false);if(m.av)toast('AV registrado: dívida e saída atualizadas juntas.');else if(['income','expense','debt','goal'].includes(m.type)&&!m.item)toast(targetScope==='shared'?'Salvo no Nosso Ritmo.':'Salvo somente no seu Ritmo.');else toast('Atualizado com sucesso.')}catch(err){toast(err.message)}}''')

# -----------------------------------------------------------------------------
# Seletor nativo de privacidade nos formulários + eventos delegados.
# -----------------------------------------------------------------------------
a += r'''

// Ritmo V1 — escopo inteligente por lançamento.
function ritmoRecordScopeDefault(){const m=state.modal||{};return m.recordScope||(state.data?.scope==='shared'?'shared':'personal')}
function ritmoEnhanceRecordScope(){
  if(!state.data?.sharing?.active)return;
  const m=state.modal,types=['income','expense','debt','goal'];
  if(!m||!types.includes(m.type)||m.item)return;
  const form=document.querySelector('#dataForm');if(!form||form.querySelector('.smart-record-scope'))return;
  let legacy=form.querySelector('[name="goal_scope"]'),value=m.recordScope||legacy?.value||ritmoRecordScopeDefault();
  legacy?.closest('label')?.remove();legacy?.remove();
  const host=form.querySelector('.action-sheet-body,.form-grid')||form,box=document.createElement('div');
  box.className='smart-record-scope full';
  box.innerHTML=`<div class="smart-scope-label"><strong>Este lançamento é</strong><small>Escolha quem pode ver.</small></div><input type="hidden" name="record_scope" value="${value}"><div class="smart-scope-segment"><button type="button" data-record-scope="personal" class="${value==='personal'?'active':''}">${ic('user',14)} Só meu</button><button type="button" data-record-scope="shared" class="${value==='shared'?'active':''}">${ic('users',14)} Do casal</button></div>`;
  host.prepend(box);
}
function ritmoEnhanceAvModal(){if(!state.modal?.av)return;const h=document.querySelector('.modal-wrap .modal-head h3');if(h)h.textContent='Registrar AV / abatimento';const meta=document.querySelector('.modal-wrap .modal-head .meta');if(meta)meta.textContent='O valor reduz a dívida e entra automaticamente em Saídas.'}
const ritmoSmartObserver=new MutationObserver(()=>{ritmoEnhanceRecordScope();ritmoEnhanceAvModal()});
ritmoSmartObserver.observe(document.documentElement,{childList:true,subtree:true});
document.addEventListener('click',e=>{
  const scope=e.target.closest?.('[data-record-scope]');if(scope){const box=scope.closest('.smart-record-scope'),hidden=box?.querySelector('input[name="record_scope"]');if(hidden)hidden.value=scope.dataset.recordScope;box?.querySelectorAll('[data-record-scope]').forEach(b=>b.classList.toggle('active',b===scope));return}
  const av=e.target.closest?.('[data-debt-av]');if(av){state.modal={type:'payment',debtId:av.dataset.debtAv,av:true};renderApp(false);return}
  const quick=e.target.closest?.('[data-shared-quick]');if(quick){state.modal={type:quick.dataset.sharedQuick,recordScope:'shared'};renderApp(false);return}
  const openDebt=e.target.closest?.('[data-open-debt]');if(openDebt){state.page='debts';state.modal=null;renderApp();toast('Gerencie esse lançamento diretamente pela dívida para manter tudo sincronizado.');return}
},false);
ritmoEnhanceRecordScope();
'''

app.write_text(a)

css=cssp.read_text()+r'''

/* Ritmo V1 — metas estratégicas, AV e casal inteligente */
.record-scope-badge,.linked-debt-badge{display:inline-flex;align-items:center;gap:4px;width:max-content;padding:4px 7px;border-radius:999px;font-size:8.5px;font-weight:750;line-height:1}.record-scope-badge.personal{color:var(--muted);background:var(--surface2)}.record-scope-badge.shared{color:var(--primary);background:color-mix(in srgb,var(--primary) 10%,var(--surface2))}.linked-debt-badge{color:var(--gold);background:color-mix(in srgb,var(--gold) 12%,var(--surface2))}.item-badge-row,.goal-badge-row,.debt-badge-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:5px}
.goal-strategy{margin:12px 0 2px;border:1px solid color-mix(in srgb,var(--sage) 22%,var(--line));border-radius:15px;background:color-mix(in srgb,var(--sage) 5%,var(--surface2));overflow:hidden}.goal-strategy summary{list-style:none;display:grid;grid-template-columns:32px 1fr 18px;gap:9px;align-items:center;padding:10px 11px;cursor:pointer}.goal-strategy summary::-webkit-details-marker{display:none}.goal-strategy-icon{width:32px;height:32px;border-radius:11px;display:grid;place-items:center;color:var(--primary);background:color-mix(in srgb,var(--sage) 14%,var(--surface-solid))}.goal-strategy summary strong{display:block;font-size:10.5px}.goal-strategy summary small{display:block;color:var(--muted);font-size:8.7px;line-height:1.4;margin-top:2px}.strategy-chevron{color:var(--muted);transition:transform .2s ease}.goal-strategy[open] .strategy-chevron{transform:rotate(90deg)}.goal-strategy-body{padding:0 11px 11px;display:grid;gap:7px}.strategy-tip{display:grid;grid-template-columns:18px 1fr;gap:6px;align-items:start;padding-top:7px;border-top:1px solid var(--line)}.strategy-tip span{width:18px;height:18px;border-radius:7px;display:grid;place-items:center;color:var(--sage);background:color-mix(in srgb,var(--sage) 9%,transparent)}.strategy-tip p{margin:1px 0 0;font-size:9px;line-height:1.45;color:var(--muted)}.goal-strategy.done{border-color:color-mix(in srgb,var(--green) 25%,var(--line))}
.debt-actions-smart{grid-template-columns:repeat(3,minmax(0,1fr))!important}.debt-actions-smart .btn{padding-left:6px!important;padding-right:6px!important;font-size:9px!important}.debt-av-btn{border-color:color-mix(in srgb,var(--gold) 38%,var(--line))!important;color:color-mix(in srgb,var(--gold) 82%,var(--text))!important;background:color-mix(in srgb,var(--gold) 7%,var(--surface-solid))!important}
.smart-record-scope{display:grid;gap:8px;padding:10px;border-radius:15px;background:var(--surface2);border:1px solid var(--line)}.smart-scope-label{display:flex;justify-content:space-between;align-items:end;gap:8px}.smart-scope-label strong{font-size:10.5px}.smart-scope-label small{font-size:8.5px;color:var(--muted)}.smart-scope-segment{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:4px;border-radius:12px;background:color-mix(in srgb,var(--text) 4%,var(--surface-solid))}.smart-scope-segment button{border:0;background:transparent;border-radius:9px;min-height:36px;display:flex;align-items:center;justify-content:center;gap:6px;font-size:9.5px;font-weight:760;color:var(--muted)}.smart-scope-segment button.active{background:var(--surface-solid);color:var(--primary);box-shadow:0 1px 5px rgba(20,35,40,.08)}
.smart-couple-hero{text-align:center}.smart-couple-hero p{max-width:520px;margin-left:auto;margin-right:auto}.couple-space-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:10px 0}.couple-space-card{border:1px solid var(--line);background:var(--surface-solid);border-radius:17px;padding:12px;display:grid;grid-template-columns:38px 1fr auto;gap:9px;align-items:center}.couple-space-icon{width:38px;height:38px;border-radius:13px;display:grid;place-items:center}.couple-space-card.personal .couple-space-icon{background:var(--surface2);color:var(--muted)}.couple-space-card.shared .couple-space-icon{background:color-mix(in srgb,var(--sage) 12%,var(--surface2));color:var(--sage)}.couple-space-card strong{display:block;font-size:10.5px}.couple-space-card small{display:block;font-size:8.5px;line-height:1.4;color:var(--muted);margin-top:2px}.couple-quick-panel,.couple-summary,.couple-privacy{margin-top:10px}.couple-quick-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.couple-quick-actions button{border:1px solid var(--line);background:var(--surface2);border-radius:14px;padding:10px;display:grid;grid-template-columns:30px 1fr;gap:7px;align-items:center;text-align:left;color:var(--text)}.couple-quick-actions button>svg{color:var(--primary)}.couple-quick-actions strong{display:block;font-size:9.5px}.couple-quick-actions small{display:block;font-size:8px;color:var(--muted);margin-top:2px}.couple-summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.couple-summary-grid>div{padding:10px;border-radius:13px;background:var(--surface2)}.couple-summary-grid span{display:block;font-size:8px;color:var(--muted)}.couple-summary-grid strong{display:block;font-size:12px;margin-top:3px}.privacy-rows{display:grid;gap:1px;border-radius:14px;overflow:hidden;background:var(--line)}.privacy-rows>div{display:grid;grid-template-columns:28px 1fr;gap:8px;align-items:center;background:var(--surface-solid);padding:10px}.privacy-rows>div>svg{color:var(--primary)}.privacy-rows strong{display:block;font-size:9.5px}.privacy-rows small{display:block;color:var(--muted);font-size:8px;margin-top:2px}
@media(max-width:760px){.couple-space-grid{grid-template-columns:1fr}.couple-space-card{grid-template-columns:38px 1fr}.couple-space-card .mini-btn{grid-column:2;width:max-content}.couple-quick-actions{grid-template-columns:1fr}.couple-summary-grid{grid-template-columns:repeat(3,1fr)}.debt-actions-smart{grid-template-columns:1fr!important}.smart-record-scope{margin-bottom:2px}}
'''
